lsm-tree.pseudocode:
def put(db, key, value):
    db.wal.append((key, value))  # 내구성: 로그 먼저
    db.memtable[key] = value  # 정렬 구조(스킵 리스트)
    if db.memtable.size() >= LIMIT:
        flush(db)

def flush(db):
    items = sorted(db.memtable.items())
    db.levels[0].insert(0, SSTable(items))  # 순차 쓰기
    db.memtable.clear()
    db.wal.truncate()
    schedule_compaction(db)  # 백그라운드 병합

def get(db, key):
    if key in db.memtable:
        return db.memtable[key]
    for level in db.levels:  # 최신 → 오래된 순
        for sst in level:
            if not sst.bloom.might_contain(key):
                continue  # 확실히 없음 → 파일 건너뜀
            v = sst.lookup(key)
            if v is not None:
                return None if v is TOMBSTONE else v
    return None
